def run_agent(user_input, tools):
    messages = [{'role':'user','content':user_input}]
    while True:
        resp = client.messages.create(model=MODEL, max_tokens=4096, tools=tools, messages=messages)
        if resp.stop_reason == 'end_turn':
            return next(b.text for b in resp.content if b.type=='text')
        messages.append({'role':'assistant','content':resp.content})
        results = []
        for block in resp.content:
            if block.type == 'tool_use':
                results.append({'type':'tool_result','tool_use_id':block.id,'content':execute_tool(block.name, block.input)})
        messages.append({'role':'user','content':results})
